package com.loopers.interfaces.api.payment
import com.loopers.application.payment.PaymentFacade;import com.loopers.domain.payment.*;import com.loopers.utils.DatabaseCleanUp;import org.assertj.core.api.Assertions.assertThat;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.context.TestConfiguration;import org.springframework.context.annotation.*;import org.springframework.context.annotation.Import
@SpringBootTest @Import(PaymentIntegrationTest.Config::class) class PaymentIntegrationTest @Autowired constructor(private val facade:PaymentFacade,private val pg:ControlledPgGateway,private val cleanup:DatabaseCleanUp){@AfterEach fun clean(){cleanup.truncateAllTables();pg.reset()};@Test fun responseLossReconcilesWithoutSecondDispatch(){pg.drop=true;val p=facade.dispatch(42,"attempt-01",1000);assertThat(p.status).isEqualTo(PaymentIntent.Status.UNKNOWN);facade.dispatch(42,"attempt-01",1000);assertThat(pg.dispatches).isEqualTo(1);pg.drop=false;assertThat(facade.reconcile(p.id).status).isEqualTo(PaymentIntent.Status.CONFIRMED);assertThat(pg.effects).isEqualTo(1)};@Test fun zeroAndMultipleLookupsDoNotGuessAndLateConflictDoesNotOverwrite(){pg.drop=true;val p=facade.dispatch(43,"attempt-02",1000);pg.found=0;assertThat(facade.reconcile(p.id).status).isEqualTo(PaymentIntent.Status.UNKNOWN);pg.found=2;org.junit.jupiter.api.assertThrows<RuntimeException>{facade.reconcile(p.id)};facade.callback(p.providerOrderId,"tx-1","CONFIRMED");assertThat(facade.callback(p.providerOrderId,"tx-1","FAILED").status).isEqualTo(PaymentIntent.Status.CONFIRMED)};@TestConfiguration class Config{@Bean @Primary fun gateway()=ControlledPgGateway()}};class ControlledPgGateway:PaymentGateway{var dispatches=0;var effects=0;var found=1;var drop=false;override fun create(userId:String,request:PaymentGateway.Request):PaymentGateway.Result{assertThat(userId).isEqualTo("135135");dispatches++;if(dispatches>1)error("second dispatch");effects++;if(drop)error("response dropped");return PaymentGateway.Result("tx-1",request.orderId,"CONFIRMED")};override fun findByOrderId(userId:String,providerOrderId:String)=List(found){PaymentGateway.Result("tx-$it",providerOrderId,"CONFIRMED")};override fun findByTransactionKey(userId:String,key:String)=PaymentGateway.Result(key,"LP-ORD-0000000042","CONFIRMED");fun reset(){dispatches=0;effects=0;found=1;drop=false}}
